-- The per-payment-type columns generated by the Jinja loop must add up to total_paid.
-- 3 payments in the source have type 'not_defined' (and value 0), which the loop
-- doesn't cover, so this test also proves those carry no money.
-- Returns orders where the split doesn't match; passes when it returns 0 rows.

select
    order_id,
    total_paid,
    credit_card_amount + boleto_amount + voucher_amount + debit_card_amount as split_total
from {{ ref('int_order_payments_agg') }}
where total_paid <> credit_card_amount + boleto_amount + voucher_amount + debit_card_amount
